use glintblade::{entities::{Enemy,EnemyCtx,EnemyKind},fx::{Fx,Particle},world::{Zone,ZoneId},combat::{Hit,Shape,Team}};
use std::time::Instant;
fn main(){let z=Zone::new(ZoneId::Bloomwild,64,64);let kinds=[EnemyKind::Sproutling,EnemyKind::ThornImp,EnemyKind::CrystalBeetle,EnemyKind::Wisp,EnemyKind::EmberHound,EnemyKind::SpittingTotem];let mut pos=[(0.0,0.0);3];let mut found=[false;3];for y in 256..276{for x in 256..276{let v=(glintblade::util::hash2(x,y,941)*3.0)as usize%3;if !found[v]{pos[v]=(x as f32,y as f32);found[v]=true;}}}assert!(found.into_iter().all(|v|v));
for cluster in[3,6,18]{for existing in[0,11980]{let mut times=Vec::new();let(mut maxparticles,mut maxproj)=(0,0);for i in 0..96{let mut fx=Fx::new(719+i);let mut ps=Vec::new();let mut hs=Vec::new();let mut es=(0..cluster).map(|i|{let(x,y)=pos[i%3];let mut e=Enemy::spawn(kinds[i%6],x,y);e.awake=true;e}).collect::<Vec<_>>();for t in 0..180{for e in&mut es{e.update(&mut EnemyCtx{player:(300.0,270.0),player_alive:true,zone:&z,fx:&mut fx,hits:&mut hs,projectiles:&mut ps,t});}fx.tick();hs.clear();}fx.particles.list.resize(existing,Particle::new(0.0,0.0));maxproj=maxproj.max(ps.len());let now=Instant::now();for e in&mut es{let hit=Hit::new(Shape::Circle{x:e.body.x,y:e.body.y,r:20.0},Team::Player,999,900001);assert!(e.on_hit(&hit,&mut EnemyCtx{player:(300.0,270.0),player_alive:true,zone:&z,fx:&mut fx,hits:&mut hs,projectiles:&mut ps,t:180}));}times.push(now.elapsed().as_secs_f64()*1000.0);maxparticles=maxparticles.max(fx.particles.list.len());std::hint::black_box((fx,ps,es));}times.sort_by(f64::total_cmp);println!("DEATH cluster={} existing={} samples={} median_ms={:.6} p95_ms={:.6} max_ms={:.6} max_particles={} max_projectiles={}",cluster,existing,times.len(),times[48],times[91],times[95],maxparticles,maxproj);}}
}
